// This code has been fully generated by an AI.

package insight

import (
	"fmt"
	"math"
	"strings"
)

// PeriodFigures are the key figures of a week or month. Health values are
// averages; 0 means "no data".
type PeriodFigures struct {
	Activities int
	DistanceM  float64
	TimerS     float64
	Load       float64
	// Seconds in HR zones 1–2, 3 and 4–5.
	EasyS, ModerateS, HardS float64
	Records                 []string // labels of new best efforts
	Sleep                   float64  // seconds
	RestingHR               float64
	HRV                     float64
}

// EasyShare and HardShare are the shares of zone time; ok is false without
// zone data.
func (f PeriodFigures) EasyShare() (float64, bool) {
	t := f.EasyS + f.ModerateS + f.HardS
	return f.EasyS / t, t > 0
}

func (f PeriodFigures) HardShare() (float64, bool) {
	t := f.EasyS + f.ModerateS + f.HardS
	return f.HardS / t, t > 0
}

// Baseline averages reference periods: sums over all periods (empty ones
// count as 0), health values over the periods that have them.
func Baseline(refs []PeriodFigures) PeriodFigures {
	var b PeriodFigures
	if len(refs) == 0 {
		return b
	}
	var acts float64
	var sleep, rhr, hrv mean
	for _, r := range refs {
		acts += float64(r.Activities)
		b.DistanceM += r.DistanceM
		b.TimerS += r.TimerS
		b.Load += r.Load
		b.EasyS += r.EasyS
		b.ModerateS += r.ModerateS
		b.HardS += r.HardS
		sleep.add(r.Sleep)
		rhr.add(r.RestingHR)
		hrv.add(r.HRV)
	}
	n := float64(len(refs))
	b.Activities = int(math.Round(acts / n))
	b.DistanceM /= n
	b.TimerS /= n
	b.Load /= n
	b.EasyS /= n
	b.ModerateS /= n
	b.HardS /= n
	b.Sleep, b.RestingHR, b.HRV = sleep.value(), rhr.value(), hrv.value()
	return b
}

type mean struct {
	sum float64
	n   int
}

func (m *mean) add(v float64) {
	if v > 0 {
		m.sum += v
		m.n++
	}
}

func (m mean) value() float64 {
	if m.n == 0 {
		return 0
	}
	return m.sum / float64(m.n)
}

// Thresholds of the review: changes below them are not mentioned.
const (
	reviewSumPct    = 0.15 // load and distance
	reviewSleepS    = 20 * 60
	reviewRHR       = 2
	reviewHRVPct    = 0.05
	reviewMaxPhrase = 4
	// MinFraction is the share of a running period below which sums are not
	// compared (a Monday says nothing about the week).
	MinFraction = 0.4
)

// Review compares a period with its baseline. fraction is the elapsed
// share of a running period (1 when complete); sums of the baseline are
// scaled with it. ref names the baseline, e.g. "4-Wochen-Schnitt".
// Only notable deviations are mentioned, at most four sentences.
func Review(cur, base PeriodFigures, fraction float64, ref string) []Statement {
	var out []Statement
	if fraction >= MinFraction {
		pct := func(label string, v, b float64) {
			b *= fraction
			if b <= 0 {
				return
			}
			d := v/b - 1
			if math.Abs(d) < reviewSumPct {
				return
			}
			word, tone := "über", ToneNeutral
			if d < 0 {
				word = "unter"
			}
			out = append(out, Statement{fmt.Sprintf("%s %.0f %% %s deinem %s", label, math.Abs(100*d), word, ref), tone})
		}
		pct("Belastung", cur.Load, base.Load)
		pct("Distanz", cur.DistanceM, base.DistanceM)
	}
	if cur.Sleep > 0 && base.Sleep > 0 {
		if d := cur.Sleep - base.Sleep; math.Abs(d) >= reviewSleepS {
			out = append(out, health("Schlaf", fmt.Sprintf("%.0f min", math.Abs(d)/60), d > 0, true))
		}
	}
	if cur.RestingHR > 0 && base.RestingHR > 0 {
		if d := cur.RestingHR - base.RestingHR; math.Abs(d) >= reviewRHR {
			out = append(out, health("Ruhepuls", fmt.Sprintf("%.0f bpm", math.Abs(d)), d > 0, false))
		}
	}
	if cur.HRV > 0 && base.HRV > 0 {
		if d := cur.HRV/base.HRV - 1; math.Abs(d) >= reviewHRVPct {
			out = append(out, health("HRV", fmt.Sprintf("%.0f %%", math.Abs(100*d)), d > 0, true))
		}
	}
	if len(out) > reviewMaxPhrase-1 && len(cur.Records) > 0 {
		out = out[:reviewMaxPhrase-1]
	}
	if n := len(cur.Records); n > 0 {
		names := cur.Records
		if len(names) > 3 {
			names = append(names[:3:3], "…")
		}
		word := "neue Bestleistung"
		if n > 1 {
			word = "neue Bestleistungen"
		}
		out = append(out, Statement{fmt.Sprintf("%d %s (%s)", n, word, strings.Join(names, ", ")), ToneGood})
	}
	if len(out) > reviewMaxPhrase {
		out = out[:reviewMaxPhrase]
	}
	return out
}

// health phrases a health deviation, e.g. "Schlaf 25 min unter deinem Üblichen".
func health(label, amount string, up, higherBetter bool) Statement {
	word := "unter"
	if up {
		word = "über"
	}
	tone := ToneBad
	if up == higherBetter {
		tone = ToneGood
	}
	return Statement{fmt.Sprintf("%s %s %s deinem Üblichen", label, amount, word), tone}
}
